UPDATE t_oa_invoice
SET deleted = #{deletedFlag, jdbcType=SMALLINT, typeHandler=net.lab1024.sa.common.mybatis.typehandler.BooleanToSmallintTypeHandler}
WHERE invoice_id = #{invoiceId}

mapper.select:
SELECT *
FROM t_oa_invoice
WHERE enterprise_id = #{enterpriseId}
AND account_number = #{accountNumber}
AND deleted = #{deletedFlag, jdbcType=SMALLINT, typeHandler=net.lab1024.sa.common.mybatis.typehandler.BooleanToSmallintTypeHandler}

    AND invoice_id != #{excludeInvoiceId}

SELECT t_oa_invoice.*,
t_oa_enterprise.enterprise_name
FROM t_oa_invoice 
LEFT JOIN t_oa_enterprise  ON t_oa_invoice.enterprise_id = t_oa_enterprise.enterprise_id

    t_oa_invoice.deleted = #{queryForm.deletedFlag, jdbcType=SMALLINT, typeHandler=net.lab1024.sa.common.mybatis.typehandler.BooleanToSmallintTypeHandler}

        AND (t_oa_invoice.invoice_heads ILIKE CONCAT('%', #{queryForm.keywords}, '%') OR t_oa_invoice.account_number ILIKE CONCAT('%', #{queryForm.keywords}, '%') OR
        t_oa_invoice.create_user_name ILIKE CONCAT('%', #{queryForm.keywords}, '%'))


        AND TO_CHAR(t_oa_invoice.create_time, 'YYYY-MM-DD') >= #{queryForm.startTime}


        AND TO_CHAR(t_oa_invoice.create_time, 'YYYY-MM-DD') <= #{queryForm.endTime}


        AND t_oa_invoice.disabled = #{queryForm.disabledFlag, jdbcType=SMALLINT, typeHandler=net.lab1024.sa.common.mybatis.typehandler.BooleanToSmallintTypeHandler}


        AND t_oa_invoice.enterprise_id = #{queryForm.enterpriseId}



    ORDER BY t_oa_invoice.create_time DESC

SELECT t_oa_invoice.*,
       t_oa_enterprise.enterprise_name
FROM t_oa_invoice
LEFT JOIN t_oa_enterprise  ON t_oa_invoice.enterprise_id = t_oa_enterprise.enterprise_id
WHERE t_oa_invoice.invoice_id = #{invoiceId}
  AND t_oa_invoice.deleted = #{deletedFlag, jdbcType=SMALLINT, typeHandler=net.lab1024.sa.common.mybatis.typehandler.BooleanToSmallintTypeHandler}
